package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity @Table(name="succession_eligibility_finding",uniqueConstraints=@UniqueConstraint(name="uk_succession_eligibility_criterion",columnNames={"agency_id","candidate_id","normalized_criterion_code"}))
public class SuccessionEligibilityFinding extends RspAuditedEntity{public enum Outcome{MET,NOT_MET,NEEDS_EVIDENCE}@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="criterion_code",nullable=false,length=80)private String criterionCode;@Column(name="normalized_criterion_code",nullable=false,length=80)private String normalizedCriterionCode;@Column(name="criterion_label",nullable=false,length=200)private String criterionLabel;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(nullable=false,length=4000)private String reason;@Column(name="employee_visible",nullable=false)private boolean employeeVisible;@Column(name="display_order",nullable=false)private int displayOrder;protected SuccessionEligibilityFinding(){}public SuccessionEligibilityFinding(String a,String candidate,String code,String label,Outcome outcome,String reason,boolean visible,int order){super(a);candidateId=requiredText(candidate,"candidateId");criterionCode=requiredText(code,"criterionCode");normalizedCriterionCode=criterionCode.toUpperCase(java.util.Locale.ROOT);criterionLabel=requiredText(label,"criterionLabel");this.outcome=java.util.Objects.requireNonNull(outcome);this.reason=requiredText(reason,"reason");employeeVisible=visible;if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getCandidateId(){return candidateId;}public String getCriterionCode(){return criterionCode;}public String getCriterionLabel(){return criterionLabel;}public Outcome getOutcome(){return outcome;}public String getReason(){return reason;}public boolean isEmployeeVisible(){return employeeVisible;}public int getDisplayOrder(){return displayOrder;}}
